public static int summeBlaetter(BinTree b) {
    if (b.isEmpty()) {
        return 0;                 // Basisfall
    }
    if (b.isLeaf()) {
        return (Integer) b.getItem();
    }
    int links = summeBlaetter(b.getLeft());
    int rechts = summeBlaetter(b.getRight());
    return links + rechts;
}

